corrected_code:
package com.retailbank.bff.controller;

import com.retailbank.bff.client.CoreBankingFeignClient;
import com.retailbank.bff.dto.DisbursementRequest;
import com.retailbank.bff.dto.DisbursementResponse;
import com.retailbank.bff.security.AuthenticatedCustomer;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/banking/accounts")
public class AccountBffController {

    private final CoreBankingFeignClient coreBankingClient;

    public AccountBffController(CoreBankingFeignClient coreBankingClient) {
        this.coreBankingClient = coreBankingClient;
    }

    @PostMapping("/{accountId}/disburse")
    public ResponseEntity<DisbursementResponse> disburseFunds(
            @PathVariable String accountId,
            @AuthenticationPrincipal AuthenticatedCustomer customer,
            @RequestBody DisbursementRequest request) {
        // Forward verified customerId from security context, ignoring any untrusted client headers
        DisbursementResponse response = coreBankingClient.executeDisbursement(customer.getCustomerId(), accountId, request);
        return ResponseEntity.ok(response);
    }
}
